export function getGeography(iso3) {
  if (!iso3) return null
  return ISO3_GEOGRAPHY[iso3.trim().toUpperCase()] ?? null
}

/** 按大洲 / 地区筛选 ISO3 代码列表 */
export function listIso3ByGeography({ continent, subregion } = {}) {
  return Object.entries(ISO3_GEOGRAPHY)
    .filter(([, geo]) => {
      if (continent && geo.continent !== continent) return false
      if (subregion && geo.subregion !== subregion) return false
      return Boolean(continent || subregion)
    })
    .map(([code]) => code)
    .sort()
}
